import java.util.*;

class Edge {
    int y, c, f, cost;
    Edge() {}
    Edge(int y, int c, int f, int cost) {
        this.y = y;
        this.c = c;
        this.f = f;
        this.cost = cost;
    }
}

public class Main {
    static List<Edge> graphEdges = new ArrayList<>();
    static final int MAXNODES = 14043;
    static List<Integer>[] adjList = new ArrayList[MAXNODES];
    static long totalCost = 0;
    static long[] distArr = new long[MAXNODES];
    static int[] parentNode = new int[MAXNODES];
    static int[] parentEdgeIdx = new int[MAXNODES];
    static int[] inQueue = new int[MAXNODES];

    static final long INF_VAL = (long)1e18;
    static int sNode = MAXNODES - 2;
    static int tNode = MAXNODES - 1;

    static {
        for (int i = 0; i < MAXNODES; i++) {
            adjList[i] = new ArrayList<>();
        }
    }

    static int residual(int idx) {
        return graphEdges.get(idx).c - graphEdges.get(idx).f;
    }

    static void findPath() {
        Arrays.fill(distArr, INF_VAL);
        Arrays.fill(parentNode, -1);
        Arrays.fill(parentEdgeIdx, -1);
        Arrays.fill(inQueue, 0);
        distArr[sNode] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(sNode);
        inQueue[sNode] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            inQueue[u] = 0;
            for (int eIdx : adjList[u]) {
                if (residual(eIdx) == 0) continue;
                int cst = graphEdges.get(eIdx).cost;
                int v = graphEdges.get(eIdx).y;
                if (distArr[v] > distArr[u] + cst) {
                    distArr[v] = distArr[u] + cst;
                    parentNode[v] = u;
                    parentEdgeIdx[v] = eIdx;
                    if (inQueue[v] == 0) {
                        inQueue[v] = 1;
                        q.offer(v);
                    }
                }
            }
        }
        int cur = tNode;
        while (cur != sNode) {
            int eIdx = parentEdgeIdx[cur];
            graphEdges.get(eIdx).f++;
            graphEdges.get(eIdx ^ 1).f--;
            cur = parentNode[cur];
        }
        totalCost += distArr[tNode];
    }

    static void connectNodes(int from, int to, int cap, int cst) {
        adjList[from].add(graphEdges.size());
        graphEdges.add(new Edge(to, cap, 0, cst));
        adjList[to].add(graphEdges.size());
        graphEdges.add(new Edge(from, 0, 0, -cst));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt();
            connectNodes(sNode, x, 1, 0);
        }

        int tt = 101;
        for (int i = 0; i < tt; i++) {
            connectNodes(1 + i * n, tNode, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            for (int j = 0; j < tt - 1; j++) {
                connectNodes(x + j * n, y + j * n + n, 1, d * (j * 2 + 1));
                connectNodes(y + j * n, x + j * n + n, 1, d * (j * 2 + 1));
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < tt - 1; j++) {
                connectNodes(i + j * n, i + j * n + n, k, 0);
            }
        }

        for (int i = 0; i < k; i++) {
            findPath();
        }

        System.out.println(totalCost);
        sc.close();
    }
}
